const upsertSongFromSpotify = `-- name: UpsertSongFromSpotify :one
INSERT INTO song_metadata (
    track_id, track_name, artist_name, popularity, year, duration_ms,
    isrc, artist_id, album_id, pending_embedding
) VALUES (
    $1, $2, $3, $4, $5, $6, $7, $8, $9, TRUE
)
ON CONFLICT (track_id) DO UPDATE SET
    track_name = coalesce(song_metadata.track_name, EXCLUDED.track_name),
    artist_name = coalesce(song_metadata.artist_name, EXCLUDED.artist_name),
    popularity = coalesce(EXCLUDED.popularity, song_metadata.popularity),
    year = coalesce(song_metadata.year, EXCLUDED.year),
    duration_ms = coalesce(song_metadata.duration_ms, EXCLUDED.duration_ms),
    isrc = coalesce(EXCLUDED.isrc, song_metadata.isrc),
    artist_id = coalesce(EXCLUDED.artist_id, song_metadata.artist_id),
    album_id = coalesce(EXCLUDED.album_id, song_metadata.album_id),
    pending_embedding = song_metadata.embedding IS NULL
RETURNING
    id, track_id, track_name, artist_name, year, genre, popularity, duration_ms,
    isrc, embedding_attempts, pending_embedding,
    (embedding IS NOT NULL)::bool AS has_embedding
`

type UpsertSongFromSpotifyParams struct {
	TrackID    sql.NullString `json:"track_id"`
	TrackName  sql.NullString `json:"track_name"`
	ArtistName sql.NullString `json:"artist_name"`
	Popularity sql.NullInt32  `json:"popularity"`
	Year       sql.NullInt32  `json:"year"`
	DurationMs sql.NullInt32  `json:"duration_ms"`
	Isrc       sql.NullString `json:"isrc"`
	ArtistID   *uuid.UUID     `json:"artist_id"`
	AlbumID    *uuid.UUID     `json:"album_id"`
}

type UpsertSongFromSpotifyRow struct {
	ID                int32          `json:"id"`
	TrackID           sql.NullString `json:"track_id"`
	TrackName         sql.NullString `json:"track_name"`
	ArtistName        sql.NullString `json:"artist_name"`
	Year              sql.NullInt32  `json:"year"`
	Genre             sql.NullString `json:"genre"`
	Popularity        sql.NullInt32  `json:"popularity"`
	DurationMs        sql.NullInt32  `json:"duration_ms"`
	Isrc              sql.NullString `json:"isrc"`
	EmbeddingAttempts int32          `json:"embedding_attempts"`
	PendingEmbedding  bool           `json:"pending_embedding"`
	HasEmbedding      bool           `json:"has_embedding"`
}

// Una canción del CSV que ya tiene embedding conserva sus datos históricos;
// solo se completan los enlaces y el ISRC. pending_embedding queda TRUE solo
// si aún no hay vector.
func (q *Queries) UpsertSongFromSpotify(ctx context.Context, arg UpsertSongFromSpotifyParams) (UpsertSongFromSpotifyRow, error) {
	row := q.db.QueryRowContext(ctx, upsertSongFromSpotify,
		arg.TrackID,
		arg.TrackName,
		arg.ArtistName,
		arg.Popularity,
		arg.Year,
		arg.DurationMs,
		arg.Isrc,
		arg.ArtistID,
		arg.AlbumID,
	)
	var i UpsertSongFromSpotifyRow
	err := row.Scan(
		&i.ID,
		&i.TrackID,
		&i.TrackName,
		&i.ArtistName,
		&i.Year,
		&i.Genre,
		&i.Popularity,
		&i.DurationMs,
		&i.Isrc,
		&i.EmbeddingAttempts,
		&i.PendingEmbedding,
		&i.HasEmbedding,
	)
	return i, err
}
